const raw = ($json.query && $json.query.offset) ? $json.query.offset : '0';
let offset = parseInt(raw, 10);
if (!Number.isFinite(offset) || offset < 0) offset = 0;
const pageSize = 10;
return [{ json: { offset, pageSize, startLine: offset + 1, endLine: offset + pageSize } }];

const offset = $('Prepare Offset').item.json.offset;
const pageSize = $('Prepare Offset').item.json.pageSize;
const raw = $json.stdout || '';
const lines = raw.split('\n').filter((l) => l.trim().length > 0);

const pairs = [];
for (const line of lines) {
  const idx = line.indexOf('<->');
  if (idx === -1) continue;
  const left = line.slice(0, idx).trim();
  const key_b = line.slice(idx + 3).trim();
  const sp = left.indexOf(' ');
  if (sp === -1) continue;
  const score = left.slice(0, sp).trim();
  const key_a = left.slice(sp + 1).trim();
  pairs.push({ score, key_a, key_b });
}

const keys = [];
for (const p of pairs) {
  keys.push(p.key_a);
  keys.push(p.key_b);
}
const keysJson = JSON.stringify(keys);
const safeKeysJson = "'" + keysJson.replace(/'/g, "'\\''") + "'";

return [{ json: { offset, pageSize, pairs, safeKeysJson } }];

// Base64, not the raw token, so the page source doesn't hand it out in
// plaintext at a glance - not real secrecy (it's trivially decodable),
// just not embarrassingly easy. The real security boundary is server-side:
// the quarantine webhook itself rejects any request whose token doesn't
// match VAULTPI_QUARANTINE_TOKEN (see quarantine-duplicate.json).
const _qt = Buffer.from($env.VAULTPI_QUARANTINE_TOKEN || '', 'utf8').toString('base64');

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

function hddPath(key) {
  return key.startsWith('photos/') ? key.slice('photos/'.length) : key;
}

const offset = $('Parse Pairs').item.json.offset;
const pageSize = $('Parse Pairs').item.json.pageSize;
const pairs = $('Parse Pairs').item.json.pairs;

let urlMap = {};
try {
  const flat = JSON.parse($json.stdout || '[]');
  for (const item of flat) urlMap[item.s3_key] = item.url;
} catch (e) {}

function side(key) {
  const path = hddPath(key);
  return `
    <div class="side">
      <img src="${urlMap[key] || ''}" loading="lazy">
      <div class="key">${escapeHtml(key)}</div>
      <button class="qbtn" data-path="${escapeHtml(path)}">Quarantine this one &rarr;</button>
    </div>`;
}

const rows = pairs.map((p) => `
  <div class="pair">
    ${side(p.key_a)}
    ${side(p.key_b)}
    <div class="score">score ${escapeHtml(p.score)}</div>
  </div>`).join('');

const prevOffset = Math.max(0, offset - pageSize);
const nextOffset = offset + pageSize;
const showPrev = offset > 0;
const showNext = pairs.length === pageSize;

const nav = `<div class="nav">
  ${showPrev ? `<a href="?offset=${prevOffset}">&larr; Previous</a>` : '<span></span>'}
  <span>showing ${pairs.length ? offset + 1 : 0}-${offset + pairs.length}</span>
  ${showNext ? `<a href="?offset=${nextOffset}">Next &rarr;</a>` : '<span></span>'}
</div>`;

const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>VaultPi Duplicate Review</title>
<style>
  body { font-family: system-ui, sans-serif; background: #111; color: #eee; margin: 0; padding: 1rem; }
  h2 { margin-top: 0; }
  .nav { display: flex; justify-content: space-between; align-items: center; margin: 1rem 0; }
  .nav a { color: #4a7; text-decoration: none; font-weight: bold; }
  .nav span { color: #999; font-size: 0.85rem; }
  .pair { display: grid; grid-template-columns: 1fr 1fr; gap: 0.5rem; background: #1a1a1a; border-radius: 8px; padding: 0.5rem; margin-bottom: 0.75rem; }
  .side img { width: 100%; max-height: 220px; object-fit: contain; border-radius: 6px; background: #000; display: block; }
  .key { font-size: 0.65rem; color: #999; word-break: break-all; margin-top: 0.25rem; }
  .score { grid-column: 1 / -1; text-align: center; font-size: 0.85rem; color: #ccc; }
  .qbtn { margin-top: 0.4rem; width: 100%; background: #2a2a2a; color: #eee; border: 1px solid #444; border-radius: 6px; padding: 0.4rem; font-size: 0.75rem; cursor: pointer; }
  .qbtn:hover:not(:disabled) { background: #3a3a3a; }
  .qbtn:disabled { opacity: 0.6; cursor: default; }
  .side.quarantined img { opacity: 0.25; filter: grayscale(1); }
  .side.quarantined .qbtn { background: #234; border-color: #367; color: #9c9; }
  .qerror { color: #f66; font-size: 0.7rem; margin-top: 0.25rem; }
</style>
</head>
<body>
  <h2>Duplicate Review</h2>
  ${nav}
  ${rows || '<p>No pairs on this page.</p>'}
  ${nav}
  <script>
    const _z = "${_qt}";
    document.querySelectorAll('.qbtn').forEach((btn) => {
      btn.addEventListener('click', async () => {
        if (btn.disabled) return;
        btn.disabled = true;
        const originalText = btn.textContent;
        btn.textContent = 'Quarantining…';
        const side = btn.closest('.side');
        const path = btn.getAttribute('data-path');
        const existingError = side.querySelector('.qerror');
        if (existingError) existingError.remove();
        try {
          const resp = await fetch('/webhook/quarantine-duplicate?path=' + encodeURIComponent(path) + '&token=' + encodeURIComponent(atob(_z)), { method: 'POST' });
          const data = await resp.json();
          if (data.ok) {
            side.classList.add('quarantined');
            btn.textContent = 'Quarantined ✓';
          } else {
            btn.disabled = false;
            btn.textContent = originalText;
            const err = document.createElement('div');
            err.className = 'qerror';
            err.textContent = 'Failed: ' + (data.error || 'unknown error');
            side.appendChild(err);
          }
        } catch (e) {
          btn.disabled = false;
          btn.textContent = originalText;
          const err = document.createElement('div');
          err.className = 'qerror';
          err.textContent = 'Request failed: ' + e;
          side.appendChild(err);
        }
      });
    });
  </script>
</body>
</html>`;

return [{ json: { html } }];
